import clsx from "clsx";
import Label from "../label/Label";

export type InputProps = {
  label: string;
  type: "text" | "password";
  id: string;
  description?: string;
  validation?: string;
  classNames?: string;
  labelClassName?: string;
  placeholder?: string;
};

const DawaInput = (props: InputProps) => {
  const {
    label,
    type,
    id,
    description,
    validation,
    classNames,
    labelClassName,
    placeholder,
  } = props;
  const invalid = validation ? "true" : "false";
  return (
    <div
      className={clsx("address-input", classNames, {
        "address-input--invalid": !!validation,
      })}
    >
      <Label id={id} className={labelClassName}>
        {label}
      </Label>
      <input
        placeholder={placeholder}
        aria-invalid={invalid}
        aria-describedby={`description-${id}`}
        aria-labelledby={validation ? `validation-${id}` : ""}
        id={id}
        type={type}
      />
      {description && (
        <div className="address-input__description" id={`description-${id}`}>
          {description}
        </div>
      )}
      {validation && (
        <div id={`validation-${id}`} className="address-input__validation">
          {validation}
        </div>
      )}
    </div>
  );
};

export default DawaInput;
